"""Generate six M5 static lessons; --write regenerates checked-in pages."""
import argparse
from build_catalog import LABS,load_registry
from build_foundation_pages import page

def table(key,heads):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+h+'</th>' for h in heads)+'</tr></thead><tbody id="'+key+'"></tbody></table></div>'

